import type { EconomicEvent, EconSource, FeedStatus, OfficialUpdate, UpdateFeed } from './types.ts';

/**
 * Merge one source's fresh reading into what is stored. Pure — the Edge Function and the
 * CLI both apply its result. Rules:
 * - every parsed event is upserted (same id = same release, so re-reading never duplicates);
 * - a stored FUTURE event of that source that the source no longer lists is deactivated
 *   (`active: false` — rescheduled or withdrawn), never deleted, and never re-activated by
 *   anything but the source listing it again;
 * - past events are history and are left alone;
 * - a failed read changes NOTHING but the status: events are never invented or dropped
 *   because a feed was down.
 */
export interface SourceResult {
  source: EconSource;
  ok: boolean;
  notModified?: boolean;
  events?: EconomicEvent[];
  error?: string | null;
}

export interface SyncPlan {
  upserts: EconomicEvent[];
  deactivate: string[];
  status: FeedStatus;
}

export function planSourceSync(stored: EconomicEvent[], result: SourceResult, prev: FeedStatus | null, now: Date): SyncPlan {
  const at = now.toISOString();
  const base: FeedStatus = prev ?? { source: result.source, checkedAt: null, lastSuccessAt: null, status: 'never', error: null, eventCount: 0, coverageUntil: null };
  if (!result.ok) return { upserts: [], deactivate: [], status: { ...base, checkedAt: at, status: 'error', error: (result.error ?? 'unavailable').slice(0, 200) } };
  if (result.notModified) return { upserts: [], deactivate: [], status: { ...base, checkedAt: at, lastSuccessAt: at, status: 'not_modified', error: null } };

  const fresh = result.events ?? [];
  const ids = new Set(fresh.map((e) => e.id));
  const todayET = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/New_York' }).format(now);
  const deactivate = stored.filter((e) => e.source === result.source && e.active && e.dateET >= todayET && !ids.has(e.id)).map((e) => e.id);
  const coverage = fresh.map((e) => e.dateET).sort().pop() ?? null;
  return {
    upserts: fresh.map((e) => ({ ...e, active: true })),
    deactivate,
    status: { source: result.source, checkedAt: at, lastSuccessAt: at, status: 'ok', error: null, eventCount: fresh.length, coverageUntil: coverage },
  };
}

/**
 * Official update feeds: items are upserted by id (never duplicated) and never deleted —
 * an item a feed stops listing simply ages out of the app's window. A failed read changes
 * only the status row.
 */
export interface UpdateResult {
  feed: UpdateFeed;
  ok: boolean;
  notModified?: boolean;
  items?: OfficialUpdate[];
  error?: string | null;
}

export function planUpdateSync(result: UpdateResult, prev: FeedStatus | null, now: Date): { upserts: OfficialUpdate[]; status: FeedStatus } {
  const at = now.toISOString();
  const base: FeedStatus = prev ?? { source: result.feed, checkedAt: null, lastSuccessAt: null, status: 'never', error: null, eventCount: 0, coverageUntil: null };
  if (!result.ok) return { upserts: [], status: { ...base, checkedAt: at, status: 'error', error: (result.error ?? 'unavailable').slice(0, 200) } };
  if (result.notModified) return { upserts: [], status: { ...base, checkedAt: at, lastSuccessAt: at, status: 'not_modified', error: null } };
  const items = result.items ?? [];
  return { upserts: items, status: { source: result.feed, checkedAt: at, lastSuccessAt: at, status: 'ok', error: null, eventCount: items.length, coverageUntil: null } };
}

/** Text safe to store as a feed error: no URLs, bounded length. */
export function feedError(e: unknown): string {
  const t = e instanceof Error ? e.message : String(e);
  return t.replace(/https?:\/\/\S+/g, '[url]').replace(/\s+/g, ' ').trim().slice(0, 200) || 'unavailable';
}
